def transform(grid):
    h, w = len(grid), len(grid[0])
    centers, hole_cols = [], set()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r-1][c] == 3 and grid[r+1][c] == 3 and
                grid[r][c-1] == 3 and grid[r][c+1] == 3):
                if grid[r][c] == 0:
                    hole_cols.add(c)
                elif grid[r][c] != 3:
                    centers.append((r, c, grid[r][c]))
    out = [row[:] for row in grid]
    # Extend through source arms; later 3 markers stop a ray. Vertical paths take priority.
    for r0, c, color in centers:
        for step in (-1, 1):
            r, passed_arm = r0 + step, False
            while 0 <= r < h:
                if grid[r][c] == 3:
                    if passed_arm:
                        break
                    passed_arm = True
                elif out[r][c] == 0:
                    out[r][c] = color
                r += step
    for r, c0, color in centers:
        for step in (-1, 1):
            c, passed_arm = c0 + step, False
            while 0 <= c < w:
                if grid[r][c] == 3:
                    if passed_arm:
                        break
                    passed_arm = True
                elif c not in hole_cols and out[r][c] == 0:
                    out[r][c] = color
                c += step
    return out
